/bin/zsh -lc "python - <<'PY'
import json,pathlib
for fn in ['policy.json','coordination.json','source.json','reference-targets.json']:
 p=pathlib.Path(fn); o=json.loads(p.read_text()); print(fn,'bytes',p.stat().st_size,'type',type(o).__name__)
 if isinstance(o,dict):
  for k,v in o.items(): print(' ',k,':',type(v).__name__,len(json.dumps(v,ensure_ascii=False)))
 elif isinstance(o,list):
  print('count',len(o))
  for i,x in enumerate(o):print(i,[(k,len(str(v))) for k,v in x.items()])
